const a=[{id:1,title:"Nesman Melesat! Kado Prestasi Futsal dan Silat Sambut Kepala Sekolah Baru",date:"2026-02-10",category:"Prestasi",image:"https://placehold.co/600x400/2563EB/FFFFFF?text=Prestasi+Futsal+Silat",summary:"SMK Pertiwi Kuningan kembali mencetak prestasi gemilang di bidang olahraga. Tim Futsal dan Pencak Silat berhasil mempersembahkan piala sebagai kado sambutan hangat bagi Kepala Sekolah baru.",content:"Februari 2026 menjadi bulan penuh prestasi bagi SMK Pertiwi Kuningan. Tim Futsal sekolah berhasil menjuarai turnamen tingkat kabupaten, sementara atlet Pencak Silat memborong medali emas dalam kejuaraan daerah. Prestasi ini menjadi kado istimewa menyambut kepemimpinan Kepala Sekolah baru, menegaskan komitmen sekolah dalam mencetak generasi juara tidak hanya di akademik tapi juga non-akademik."},{id:2,title:"SMK Pertiwi Tampilkan 'Teater Simpai Sandekala' di Karnaval Budaya",date:"2025-10-05",category:"Seni & Budaya",image:"https://placehold.co/600x400/DC2626/FFFFFF?text=Teater+Simpai+Sandekala",summary:"Memeriahkan HUT Kabupaten Kuningan ke-527, siswa SMK Pertiwi Kuningan memukau penonton dengan pertunjukan teatrikal 'Simpai Sandekala' di Jalan Siliwangi.",content:"Dalam rangka memeriahkan Hari Jadi Kuningan yang ke-527, SMK Pertiwi Kuningan turut ambil bagian dalam Karnaval Budaya. Mengusung tema kearifan lokal, para siswa menampilkan 'Teater Simpai Sandekala' yang menggabungkan seni peran, tari, dan musik tradisional. Penampilan ini mendapat apresiasi meriah dari masyarakat yang memadati sepanjang Jalan Siliwangi."},{id:3,title:"Program 'Gratiskan 30 Persen Siswa' untuk Pemerataan Pendidikan",date:"2025-04-12",category:"Pengumuman",image:"https://placehold.co/600x400/16A34A/FFFFFF?text=Beasiswa+Pendidikan",summary:"SMK Pertiwi Kuningan meluncurkan program beasiswa masif, menggratiskan biaya pendidikan bagi 30% siswa sebagai bentuk kepedulian sosial.",content:"Sebagai bentuk komitmen terhadap pemerataan akses pendidikan berkualitas, SMK Pertiwi Kuningan mengumumkan program subsidi silang dan beasiswa penuh. Sebanyak 30% siswa dari keluarga kurang mampu namun berprestasi akan mendapatkan pembebasan biaya pendidikan. Program ini diharapkan dapat memutus rantai kemiskinan melalui bekal keterampilan vokasi yang mumpuni."},{id:4,title:"Pertama di Indonesia! Kurikulum Balap Motor Yamaha",date:"2024-08-03",category:"Kurikulum",image:"https://placehold.co/600x400/2563EB/FFFFFF?text=Yamaha+Racing+Academy",summary:"Kerjasama eksklusif dengan Yamaha Racing Indonesia, SMK Pertiwi Kuningan menjadi sekolah pertama yang menerapkan kurikulum standar balap motor profesional.",content:"SMK Pertiwi Kuningan mencatatkan sejarah baru sebagai SMK pertama di Indonesia yang mengadopsi kurikulum Balap Motor resmi dari Yamaha Racing Indonesia. Kerjasama ini memungkinkan siswa Teknik Sepeda Motor (TSM) belajar langsung teknik mekanik balap, setup mesin kompetisi, dan manajemen tim balap profesional langsung dari ahlinya."},{id:5,title:"HUT Ke-45 'Casperday' Dimeriahkan Band Armada",date:"2024-06-07",category:"Event",image:"https://placehold.co/600x400/9333EA/FFFFFF?text=Casperday+Anniversary",summary:"Puncak perayaan ulang tahun sekolah 'Casperday' berlangsung pecah dengan penampilan spesial dari Band Armada yang menghibur ribuan siswa dan alumni.",content:"Momen ulang tahun ke-45 SMK Pertiwi Kuningan (Casperday) digelar dengan sangat meriah. Panggung utama diguncang oleh penampilan guest star Band Armada yang membawakan hits-hits andalannya. Acara ini juga menjadi ajang reuni akbar alumni dan pameran karya siswa (Job Fair & Edu Fair) yang terbuka untuk umum."},{id:6,title:"Kunjungan Studi Banding Axioo Class Program",date:"2024-04-30",category:"Kunjungan",image:"https://placehold.co/600x400/EA580C/FFFFFF?text=Studi+Banding+Axioo",summary:"Menjadi rujukan nasional, SMK Pertiwi menerima kunjungan studi banding dari 13 SMK se-Indonesia terkait implementasi Axioo Class Program.",content:"Sebagai salah satu SMK Rujukan Nasional level A untuk Axioo Class Program, SMK Pertiwi Kuningan menerima kunjungan dari 13 SMK berbagai daerah. Kunjungan ini bertujuan untuk mempelajari best practice pengelolaan kelas industri, sinkronisasi kurikulum, dan budaya kerja industri yang telah sukses diterapkan di sini."},{id:7,title:"Support Yamaha Indonesia untuk Tim Balap Sekolah",date:"2024-04-19",category:"Prestasi",image:"https://placehold.co/600x400/0284C7/FFFFFF?text=Yamaha+Racing+Team",summary:"PT. Yamaha Indonesia Motor Manufacturing (YIMM) menyerahkan bantuan engine dan chasis untuk riset tim balap SMK Pertiwi Kuningan.",content:"Dukungan industri terus mengalir. PT. YIMM secara resmi menyerahkan bantuan berupa unit mesin dan sasis Yamaha MX King untuk mendukung riset dan pengembangan Tim Balap SMK Pertiwi. Bantuan ini diharapkan dapat mendongkrak prestasi tim sekolah di ajang balap daerah maupun nasional."}];export{a as n};
